/**
 * Seed step 002 — SYNTHETIC personnel, duty areas, assignments and manpower history (Phase 3).
 * Everything here is fabricated: officer names carry "Demo", service numbers are SYN-######,
 * area names are flagged "(synthetic)". History is generated by driving the real domain services
 * with a back-dated clock, so approvals, dispositions, notifications and audit are consistent.
 */
import type { DB } from "./connection";
import { all, one, run } from "./connection";
import type { RoleCode } from "../domain/catalogue";
import { addDays, newId, setClock } from "../domain/core";
import { HQ_ID, loadActor } from "../domain/policy";
import { hashPassword } from "../domain/auth";
import { audit } from "../domain/audit";
import { nameKey } from "../domain/personnel";
import { acceptDecision, decideAssignment, decideException, initiateTransfer, proposeAssignment, raiseException, releaseAssignment, releaseDecision, renewAssignment } from "../domain/assignments";
import { addContributionEntries, buildRoster, contributionAction, createManpowerRequest, manpowerAction, rosterAction, setRequirement } from "../domain/manpower";
import { SYNTHETIC_DEV_PASSWORD } from "./constants";

type U = [id: string, username: string, name: string, title: string, role: RoleCode, org: string];

